const metrics = $input.first().json;

const counts = {};

for (const [key, value] of Object.entries(metrics)) {
  counts[key] = Number(value ?? 0);
}

const alerts = [];

if (counts.exhausted_event_failures > 0) {
  alerts.push("Events exhausted retries");
}

if (counts.exhausted_hubspot_failures > 0) {
  alerts.push("HubSpot jobs exhausted retries");
}

if (counts.stale_received_events > 0) {
  alerts.push("Events have been waiting over 15 minutes");
}

if (counts.identity_reviews > 0) {
  alerts.push("Customer identities need review");
}

if (counts.change_reviews > 0) {
  alerts.push("Contact change proposals need review");
}

return [{
  json: {
    status: alerts.length ? "attention_required" : "healthy",
    checked_at: new Date().toISOString(),
    metrics: counts,
    alerts
  }
}];
